const order = $input.first().json.body;
const type = order.type || 'import';
const isImport = type === 'import';
const email = order.email || '';

const items = order.items || [];
let itemRows = '';
let totalAmount = 0;

for (const item of items.slice(0, 10)) {
  const name = item.product_name || item.name || 'SP';
  const qty = item.quantity || 0;
  const price = item.price || item.unit_price || 0;
  const amount = qty * price;
  totalAmount += amount;
  itemRows += `<tr><td>${name}</td><td>${qty}</td><td>${new Intl.NumberFormat('vi-VN').format(amount)} đ</td></tr>`;
}
if (items.length > 10) itemRows += `<tr><td colspan="3">... và ${items.length - 10} sản phẩm khác</td></tr>`;

const html = `<h2>${isImport ? '📦 Phiếu nhập kho mới' : '📤 Đơn xuất kho mới'}</h2><table border="1" cellpadding="6" cellspacing="0"><tr><th>Sản phẩm</th><th>SL</th><th>Thành tiền</th></tr>${itemRows || '<tr><td colspan="3">Không có sản phẩm</td></tr>'}</table><p>Loại: <b>${isImport ? 'Nhập kho' : 'Xuất kho'}</b> — Số SP: <b>${items.length}</b> — Tổng tiền: <b>${new Intl.NumberFormat('vi-VN').format(totalAmount)} đ</b></p><p>Người tạo: ${order.user || 'ANSER User'}</p><p>Ghi chú: ${order.notes || 'không có'}</p>`;

return [{ json: { email, email_subject: isImport ? 'Phiếu nhập kho mới' : 'Đơn xuất kho mới', email_html: html, summary: { type, items: items.length, total: totalAmount } } }];
